// 难度档位（AI 审阅综合档 1~5）的 Tag 展示规则，题目列表 / 题目详情 / 后台审阅列表共用一份口径。
//
// TDesign 的 Tag 只有 default / primary / success / warning / danger 五种合法 theme，
// 正好够五档各用一种颜色，按难度单调递进：灰 → 绿 → 蓝 → 橙 → 红。
// 最高档（挑战）再叠一层 variant 权重：1~4 用浅底彩字（light），5 用实底白字（dark），
// 让「最难的题」在列表和详情里都能一眼跳出来，而不会与「困难」混成同一个颜色。
//
// 历史坑：第五档曾被写成 "error"（TDesign 没有该主题），Tag 照常拼出 t-tag--error
// 但样式表里没有这条规则，只剩基础样式（白字 + 透明底），最高难度在浅色卡片上几乎不可见。
// 所以这里把 theme 取值收紧成字面量联合，越界值（含未标注的 0）一律回落 default + light。
export type DifficultyTheme = "default" | "success" | "primary" | "warning" | "danger";
export type DifficultyVariant = "light" | "dark";

const DIFFICULTY_THEME: Record<number, DifficultyTheme> = {
  1: "default", // 入门：灰
  2: "success", // 基础：绿
  3: "primary", // 进阶：蓝
  4: "warning", // 困难：橙
  5: "danger", // 挑战：红（配 dark 变体，实底强调）
};

/** 难度档位对应的 Tag 主题；越界值（含未标注的 0）回落 default */
export function GetDifficultyTheme(grade: number): DifficultyTheme {
  return DIFFICULTY_THEME[grade] ?? "default";
}

/** 难度档位的视觉权重：最高档用实底强调，其余用浅底 */
export function GetDifficultyVariant(grade: number): DifficultyVariant {
  return grade >= 5 ? "dark" : "light";
}
